presets.css:
/* =========================================
   Puff · 线下常用模板 - 香脆薄巧
   色系：#8E97A3 / #D5ECF2 / #FADAE2 / #FFFAE8
   ========================================= */

:root {
  --sweet-slate: #8E97A3;
  --sweet-blue: #D5ECF2;
  --sweet-pink: #FADAE2;
  --sweet-cream: #FFFAE8;
  --sweet-text: #5C636E; /* 比灰蓝深一点，保证正文可读性 */
}

/* —— 入口列表 —— */
.off-app {
  --off-list-bg: var(--sweet-cream);
  --off-list-border: rgba(142, 151, 163, 0.15); /* 灰蓝低透明度边框，柔和不突兀 */
  --off-list-radius: 24px; /* 圆角加大，更甜美 */
  --off-list-ava-size: 56px; /* 头像稍微大一点，更可爱 */
}
html[data-theme="dark"] .off-app {
  --off-list-bg: #2A2D33;
  --off-list-border: rgba(213, 236, 242, 0.1);
}

/* 筛选按钮 */
.off-inbox-filter button {
  color: var(--sweet-slate);
  background: transparent;
}
.off-inbox-filter button.on {
  color: var(--sweet-text);
  background: var(--sweet-pink); /* 选中用淡粉 */
}
html[data-theme="dark"] .off-inbox-filter button.on {
  background: rgba(250, 218, 226, 0.2);
  color: var(--sweet-pink);
}

/* 列表行 */
.off-list {
  background: var(--off-list-bg);
  border: 1px solid var(--off-list-border);
  border-radius: var(--off-list-radius);
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(142, 151, 163, 0.06); /* 加一点温柔投影 */
}
.off-list-btn {
  padding: 16px 14px 16px 18px; /* 略微调整内边距 */
}
.off-list-body strong {
  font-size: 1.35rem;
  color: var(--sweet-text);
}
.off-list-body span {
  opacity: 0.85;
  color: var(--sweet-slate);
}
.off-list-go.is-new {
  font-size: 20px;
  font-weight: 300;
  color: var(--sweet-blue); /* 未读箭头用浅蓝 */
}

/* —— 当面共处 —— */
.off-app.off-app-session {
  --off-card-user: var(--sweet-blue);   /* 我方卡片：浅蓝 */
  --off-card-peer: var(--sweet-pink);   /* 对方卡片：淡粉 */
  --off-card-border: rgba(142, 151, 163, 0.12);
  --off-card-shadow: 0 8px 24px rgba(142, 151, 163, 0.1); /* 柔和漫反射阴影 */
  --off-prose-font: "Quicksand", "PingFang SC", "Noto Serif SC", sans-serif; /* 圆体，更甜 */
  --off-dock-bg: rgba(255, 250, 232, 0.95); /* 底栏用奶油黄 */
  color: var(--sweet-text);
}
html[data-theme="dark"] .off-app.off-app-session {
  --off-card-user: #2F3338;   /* 暗色下我方卡片：深灰蓝 */
  --off-card-peer: #3D2E33;   /* 暗色下对方卡片：深粉灰 */
  --off-card-border: rgba(213, 236, 242, 0.08);
  --off-card-shadow: 0 6px 28px rgba(0, 0, 0, 0.4);
  --off-dock-bg: rgba(42, 45, 51, 0.94);
}

/* 无壁纸时当面页默认底色：奶油黄 */
.off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {
  background: var(--sweet-cream);
}
html[data-theme="dark"] .off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {
  background: #1E2024;
}

/* 当面顶栏 */
.off-app.off-app-session .off-stage-head {
  border-bottom: 1px solid rgba(142, 151, 163, 0.1);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
html[data-theme="dark"] .off-app.off-app-session .off-stage-head {
  border-bottom-color: rgba(213, 236, 242, 0.06);
}
.off-app.off-app-session .off-stage-scene {
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--sweet-slate);
}

/* 日记卡片 */
.off-app.off-app-session .off-passage-sheet {
  background: var(--off-card-peer);
  border: 1px solid var(--off-card-border);
  box-shadow: var(--off-card-shadow);
  border-radius: 20px; /* 圆角加大 */
}
.off-app.off-app-session .off-passage.is-me .off-passage-sheet {
  background: var(--off-card-user);
}

/* 段落旁「推演」 */
.off-app .off-thinking-chip {
  background: rgba(213, 236, 242, 0.6); /* 浅蓝底 */
  color: var(--sweet-slate);
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 11px;
  letter-spacing: 0.04em;
}
html[data-theme="dark"] .off-app .off-thinking-chip {
  background: rgba(250, 218, 226, 0.15);
  color: var(--sweet-pink);
}

/* 正文 */
.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain {
  font-family: var(--off-prose-font);
  line-height: 1.85;
  font-size: 14.5px;
  color: var(--sweet-text);
}
.off-app.off-app-session .off-prose-dial {
  font-family: var(--off-prose-font);
  line-height: 1.85;
  font-size: 14.5px;
  font-style: normal;
  font-weight: 600;
  color: var(--sweet-slate); /* 对话用灰蓝，更有层次 */
}
.off-app.off-app-session .off-passage.is-me .off-prose-dial {
  font-weight: 500;
  color: var(--sweet-text);
}

/* 底栏输入 */
.off-app.off-app-session .off-stage-dock {
  background: var(--off-dock-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-top: 1px solid rgba(142, 151, 163, 0.1);
}
.off-compose-bar {
  background: #fff;
  border: 1px solid rgba(142, 151, 163, 0.15);
  border-radius: 999px;
}
html[data-theme="dark"] .off-compose-bar {
  background: #2F3338;
  border-color: rgba(213, 236, 242, 0.1);
}
.off-compose-send {
  background: var(--sweet-pink); /* 发送按钮用淡粉 */
  color: var(--sweet-text);
  border-radius: 50%;
  transition: transform 0.2s ease;
}
.off-compose-send:active {
  transform: scale(0.92);
}
html[data-theme="dark"] .off-compose-send {
  background: var(--sweet-blue);
  color: #1E2024;
}
